 private function call($case,$method,array $args=[]){return (new ReflectionMethod($case,$method))->invokeArgs($case,$args);}
 public function testAuthenticatedPhotoCropReplacementAndReorderKeepStaleProofsHeld():void {
  DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();$case=new RenderArtifactCertificationTest();$input=$this->call($case,'deterministicFixture');$schema=[['key'=>'photo_1','type'=>'image_reference','required'=>true],['key'=>'photo_2','type'=>'image_reference','required'=>true]];$args=[$input,$schema,['photo_1'=>'digiforge/product-factory/source.png','photo_2'=>'digiforge/product-factory/source.png']];$method=new ReflectionMethod($case,'familyPayload');$method->invokeArgs($case,[&$args[0],$args[1],$args[2]]);$input=$args[0];$operator=get_current_user_id();$customer=self::factory()->user->create(['role'=>'subscriber']);$grant=$this->call($case,'editorGrant',[$input,$customer]);$repo=new CustomerEditorRepository();$rgba='';for($i=0;$i<2048;$i++)$rgba.=chr($i%251)."\x40\x80\xff";$png=RasterArtworkCodec::encode(64,32,$rgba);$calls=[];$block=function($pre,$args,$url)use(&$calls){$calls[]=$url;return new WP_Error('offline');};add_filter('pre_http_request',$block,PHP_INT_MAX,3);
  try{wp_set_current_user($customer);$workflow=new CustomerEditorWorkflow();$workflow->register();rest_get_server();do_action('rest_api_init');$request=function($action,$body)use($workflow,$grant){$r=new WP_REST_Request('POST','/digiforge/v1/customer-editor/'.$grant['session_key'].'/'.$action);$r->set_param('session',$grant['session_key']);$r->set_header('X-WP-Nonce',wp_create_nonce('wp_rest'));$r->set_header('Content-Type','application/json');$r->set_body(json_encode($body));$response=rest_get_server()->dispatch($r);return $response->is_error()?$response->as_error():$response;};
   $invalidNonce=new WP_REST_Request('POST','/digiforge/v1/customer-editor/'.$grant['session_key'].'/upload');$invalidNonce->set_header('Content-Type','application/json');$invalidNonce->set_body('{}');self::assertSame(403,rest_get_server()->dispatch($invalidNonce)->get_status());
   $payload=['request_key'=>'crop-first','expected_head'=>null,'mode'=>'PHOTO','image_base64'=>base64_encode($png),'image_field'=>'photo_1','fields'=>[],'selection'=>['x'=>0,'y'=>0,'width'=>32,'height'=>32],'rights_confirmed'=>true,'processing_consent'=>true];$first=$request('upload',$payload);self::assertNotWPError($first);$first=$first->get_data();self::assertSame('PHOTO',$first['images']['photo_1']['generation']['mode']);self::assertSame(32,$first['images']['photo_1']['cutout']['width_px']);self::assertFalse($first['artwork_certified']);self::assertSame($first,$request('upload',$payload)->get_data());
   self::assertWPError($request('fields',['expected_head'=>$first['sha256'],'image_order'=>['photo_1','photo_2']]));
   $payload['request_key']='crop-second';$payload['expected_head']=$first['sha256'];$payload['image_field']='photo_2';$payload['selection']['x']=32;$second=$request('upload',$payload);self::assertNotWPError($second);$second=$second->get_data();self::assertSame($first['sha256'],$second['parent_sha256']);
   $reordered=$request('fields',['expected_head'=>$second['sha256'],'image_order'=>['photo_2','photo_1']]);self::assertNotWPError($reordered);$reordered=$reordered->get_data();self::assertSame($second['images']['photo_2'],$reordered['images']['photo_1']);self::assertSame($second['images']['photo_1'],$reordered['images']['photo_2']);self::assertSame($second['sha256'],$reordered['parent_sha256']);self::assertWPError($request('fields',['expected_head'=>$second['sha256'],'image_order'=>['photo_1','photo_2']]));
   $v=$repo->view($grant['session_key']);self::assertSame('PHOTO',$v['images']['photo_1']['kind']);self::assertSame('BLOCKED',$v['product_preview']['state']);self::assertWPError($repo->approve($grant['session_key'],$first['sha256'],str_repeat('a',64)));self::assertWPError($request('fields',['expected_head'=>$reordered['sha256'],'image_order'=>['photo_1','photo_1']]));
   $payload['expected_head']=$reordered['sha256'];$payload['request_key']='outside';$payload['selection']['width']=65;self::assertWPError($request('upload',$payload));self::assertSame($reordered['sha256'],$repo->view($grant['session_key'])['version_sha256']);
   $jpeg=file_get_contents(__DIR__.'/../fixtures/customer-editor/oriented-synthetic.jpg');$payload['request_key']='oriented-jpeg';$payload['image_base64']=base64_encode($jpeg);$payload['selection']=['x'=>0,'y'=>0,'width'=>16,'height'=>32];
   $jpegVersion=$request('upload',$payload);self::assertNotWPError($jpegVersion);$jpegVersion=$jpegVersion->get_data();self::assertSame(6,$jpegVersion['images']['photo_2']['generation']['normalization']['orientation_applied']);self::assertSame([32,64],$jpegVersion['images']['photo_2']['generation']['crop']['source_size_px']);self::assertSame(hash('sha256',$jpeg),$jpegVersion['images']['photo_2']['original']['sha256']);
   $payload['request_key']='malformed';$payload['expected_head']=$jpegVersion['sha256'];$payload['image_base64']=base64_encode('<svg><script/></svg>');self::assertWPError($request('upload',$payload));self::assertSame($jpegVersion['sha256'],$repo->view($grant['session_key'])['version_sha256']);
   wp_set_current_user(self::factory()->user->create(['role'=>'subscriber']));self::assertWPError($repo->view($grant['session_key']));wp_set_current_user($operator);self::assertSame('customer_editor_photo_is_not_cutout',$repo->operatorIntake($grant['session_key'],$jpegVersion['sha256'],'photo_1',[],'not-alpha')->get_error_code());self::assertSame('customer_editor_photo_preview_binding_required',$repo->publish($grant['session_key'],['version_sha256'=>$jpegVersion['sha256'],'render_id'=>1,'panel'=>'front','cutout_keys'=>['photo_1'=>'not-alpha','photo_2'=>'not-alpha'],'mockup_evidence_reference'=>'none','mockup_evidence_sha256'=>str_repeat('a',64)])->get_error_code());self::assertSame([],$calls);self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));
  }finally{remove_filter('pre_http_request',$block,PHP_INT_MAX);wp_set_current_user($operator);}
 }
